import React from 'react'
import { sql } from './lib/db'
import { CheckSquare, Compass, Users, Sparkles, Home, Image as ImageIcon, BookOpen, Settings, Calendar, Star, MapPin } from 'lucide-react'
import TaskList from './components/TaskList'
import CollectionList from './components/CollectionList'
import AddModal from './components/AddModal'
import ResidentList from './components/ResidentList'

export default async function IslandDashboard() {
    let islands = await sql`SELECT * FROM islands LIMIT 1`
    let island = islands[0]

    if (!island) {
        const insertedIslands = await sql`
      INSERT INTO islands (name, hemisphere, player_name) 
      VALUES ('Lavender Reef', 'Northern', 'Luther') 
      RETURNING *
    `
        island = insertedIslands[0]

        await sql`
      INSERT INTO tasks (island_id, title, category, target, current) VALUES 
      (${island.id}, 'Water all hybrid flowers', 'Daily', 5, 5),
      (${island.id}, 'Check recycling bin', 'Daily', 1, 0),
      (${island.id}, 'Catch a butterfly', 'Milestone', 1, 1)
    `
        await sql`
      INSERT INTO collections (island_id, category, name, collected) VALUES 
      (${island.id}, 'Fish', 'Neon Tetra', true),
      (${island.id}, 'Insects', 'Emperor Butterfly', false)
    `
        await sql`
      INSERT INTO residents (island_id, name, species, personality) VALUES 
      (${island.id}, 'Julian', 'Horse', 'Smug'),
      (${island.id}, 'Diana', 'Deer', 'Snooty')
    `
    }

    const tasks = await sql`SELECT * FROM tasks WHERE island_id = ${island.id}`
    const collections = await sql`SELECT * FROM collections WHERE island_id = ${island.id}`
    const residents = await sql`SELECT * FROM residents WHERE island_id = ${island.id}`

    return (
        <div className="min-h-screen bg-[#F6F4F8] text-[#2E2733] flex font-sans">
            {/* Sidebar Navigation */}
            <aside className="w-64 bg-[#2A2030] text-[#E8E2EC] p-6 flex flex-col justify-between hidden md:flex shadow-lg">
                <div>
                    <div className="bg-[#3D3044] p-4 rounded-2xl mb-8 border border-[#52435C]">
                        <p className="text-xs text-[#B8ACC2]">Welcome to</p>
                        <h2 className="text-xl font-bold tracking-wide text-white">{island.name}</h2>
                    </div>
                    <nav className="space-y-2 text-sm">
                        <a href="#" className="flex items-center gap-3 px-3 py-2.5 rounded-xl bg-[#52435C] text-white font-medium">
                            <Home className="w-4 h-4 text-[#D1BCE3]" /> Overview
                        </a>
                        <a href="#" className="flex items-center gap-3 px-3 py-2.5 rounded-xl hover:bg-[#3D3044] text-[#B8ACC2] transition-colors">
                            <CheckSquare className="w-4 h-4" /> Tasks
                        </a>
                        <a href="#" className="flex items-center gap-3 px-3 py-2.5 rounded-xl hover:bg-[#3D3044] text-[#B8ACC2] transition-colors">
                            <Compass className="w-4 h-4" /> Collections
                        </a>
                        <a href="#" className="flex items-center gap-3 px-3 py-2.5 rounded-xl hover:bg-[#3D3044] text-[#B8ACC2] transition-colors">
                            <Users className="w-4 h-4" /> Residents
                        </a>
                        <a href="#" className="flex items-center gap-3 px-3 py-2.5 rounded-xl hover:bg-[#3D3044] text-[#B8ACC2] transition-colors">
                            <ImageIcon className="w-4 h-4" /> Gallery
                        </a>
                        <a href="#" className="flex items-center gap-3 px-3 py-2.5 rounded-xl hover:bg-[#3D3044] text-[#B8ACC2] transition-colors">
                            <BookOpen className="w-4 h-4" /> Notes
                        </a>
                    </nav>
                </div>
                <div className="text-xs text-[#93859E] border-t border-[#43354C] pt-4 flex items-center gap-2">
                    <Settings className="w-4 h-4" /> Version 1.0.4
                </div>
            </aside>

            {/* Main Content Area */}
            <main className="flex-1 p-6 md:p-10 overflow-y-auto">
                {/* Top Illustrated Banner */}
                <div className="relative w-full h-48 md:h-56 rounded-3xl overflow-hidden mb-8 shadow-sm bg-gradient-to-r from-[#4A3556] via-[#6D517D] to-[#9B77AD] flex items-end p-6 md:p-8 text-white">
                    <div className="absolute inset-0 opacity-20 bg-[radial-gradient(#fff_1px,transparent_1px)] [background-size:16px_16px]"></div>

                    <div className="relative z-10 flex flex-col md:flex-row justify-between items-start md:items-end w-full gap-4">
                        <div>
                            <div className="flex items-center gap-2 text-xs font-semibold uppercase tracking-wider text-[#E8E2EC] mb-1">
                                <Sparkles className="w-3.5 h-3.5 text-[#D1BCE3]" /> Welcome back!
                            </div>
                            <h1 className="text-3xl md:text-4xl font-extrabold tracking-tight">Welcome back, {island.player_name}!</h1>
                            <p className="text-sm text-[#E8E2EC] mt-1">Here is an overview of your island on {island.name} 🌿</p>
                        </div>

                        <div className="flex items-center gap-3">
                            <div className="bg-[#2A2030]/80 backdrop-blur-md px-4 py-2.5 rounded-2xl border border-[#7A508C] text-xs font-medium text-white flex items-center gap-4">
                                <span className="flex items-center gap-1.5"><Calendar className="w-3.5 h-3.5 text-[#D1BCE3]" /> 20 Sep 2026</span>
                                <span>•</span>
                                <span>{island.hemisphere} Hemisphere</span>
                            </div>
                            <AddModal islandId={island.id} />
                        </div>
                    </div>
                </div>

                {/* Dashboard Grid */}
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">

                    {/* Section 1: Overview Card */}
                    <div className="space-y-4">
                        <div className="flex items-center justify-between">
                            <h3 className="font-bold text-base text-[#2A2030] flex items-center gap-2">
                                <Star className="w-4.5 h-4.5 text-[#7A508C]" /> Overview
                            </h3>
                        </div>
                        <div className="p-5 bg-white rounded-3xl border border-[#E4DFEA] shadow-xs space-y-4">
                            <div className="flex justify-between items-center text-sm">
                                <span className="text-[#665773]">Island Rating</span>
                                <div className="flex text-amber-500 gap-0.5">
                                    <Star className="w-3.5 h-3.5 fill-current" />
                                    <Star className="w-3.5 h-3.5 fill-current" />
                                    <Star className="w-3.5 h-3.5 fill-current" />
                                    <Star className="w-3.5 h-3.5 fill-current" />
                                    <Star className="w-3.5 h-3.5 text-gray-300" />
                                </div>
                            </div>
                            <div className="flex justify-between items-center text-sm border-t border-[#F0EBF4] pt-3">
                                <span className="text-[#665773]">Dream Address</span>
                                <span className="font-mono text-xs text-[#2A2030] bg-[#F6F4F8] px-2.5 py-1 rounded-xl">DA-1234-5678-9101</span>
                            </div>
                            <div className="flex justify-between items-center text-sm border-t border-[#F0EBF4] pt-3">
                                <span className="text-[#665773]">Residents</span>
                                <span className="font-semibold text-xs text-[#2A2030]">8 / 10</span>
                            </div>
                        </div>
                    </div>

                    {/* Section 2: Tasks List */}
                    <div className="space-y-4">
                        <div className="flex items-center justify-between">
                            <h3 className="font-bold text-base text-[#2A2030] flex items-center gap-2">
                                <CheckSquare className="w-4.5 h-4.5 text-[#8A629B]" /> Tasks
                            </h3>
                            <span className="text-xs text-[#7A508C] font-medium cursor-pointer hover:underline">View all</span>
                        </div>
                        <TaskList initialTasks={tasks} />
                    </div>

                    {/* Section 3: Latest Photo Preview */}
                    <div className="space-y-4">
                        <div className="flex items-center justify-between">
                            <h3 className="font-bold text-base text-[#2A2030] flex items-center gap-2">
                                <ImageIcon className="w-4.5 h-4.5 text-[#5C3D6B]" /> Latest Photo
                            </h3>
                            <span className="text-xs text-[#7A508C] font-medium cursor-pointer hover:underline">View all</span>
                        </div>
                        <div className="p-3 bg-white rounded-3xl border border-[#E4DFEA] shadow-xs">
                            <div className="w-full h-32 rounded-2xl bg-gradient-to-tr from-[#52435C] to-[#8A629B] flex items-center justify-center text-white text-xs font-medium mb-3 shadow-inner">
                                📸 Lavender Path View
                            </div>
                            <p className="text-xs text-[#665773] px-1 font-medium">My small forest path ✨</p>
                            <p className="text-[10px] text-[#93859E] px-1">19 Sep 2026</p>
                        </div>
                    </div>

                    {/* Section 4: Collections Grid */}
                    <div className="space-y-4">
                        <div className="flex items-center justify-between">
                            <h3 className="font-bold text-base text-[#2A2030] flex items-center gap-2">
                                <Compass className="w-4.5 h-4.5 text-[#7A508C]" /> Collections
                            </h3>
                            <span className="text-xs text-[#7A508C] font-medium cursor-pointer hover:underline">View all</span>
                        </div>
                        <CollectionList initialCollections={collections} />
                    </div>
                    {/* Section 5: Island Map Snapshot */}
                    <div className="space-y-4">
                        <div className="flex items-center justify-between">
                            <h3 className="font-bold text-base text-[#2A2030] flex items-center gap-2">
                                <MapPin className="w-4.5 h-4.5 text-[#8A629B]" /> My Island
                            </h3>
                        </div>
                        <div className="p-3 bg-white rounded-3xl border border-[#E4DFEA] shadow-xs text-center">
                            <div className="w-full h-28 rounded-2xl bg-[#EAE2F0] border border-[#D5C6E3] flex items-center justify-center text-[#7A508C] text-xs font-semibold mb-3">
                                🗺️ Island Layout Map
                            </div>
                            <button className="w-full py-2 bg-[#F4EEF8] hover:bg-[#EAE2F0] text-[#7A508C] font-semibold rounded-xl text-xs transition-colors">
                                View Map
                            </button>
                        </div>
                    </div>

                    {/* Section 6: Residents List */}
                    <div className="space-y-4">
                        <div className="flex items-center justify-between">
                            <h3 className="font-bold text-base text-[#2A2030] flex items-center gap-2">
                                <Users className="w-4.5 h-4.5 text-[#5C3D6B]" /> Residents
                            </h3>
                            <span className="text-xs text-[#7A508C] font-medium cursor-pointer hover:underline">View all</span>
                        </div>
                        <div className="space-y-3">
                            <ResidentList initialResidents={residents} />
                            <button className="w-full py-2 bg-[#52435C] hover:bg-[#3D3044] text-white font-medium rounded-2xl text-xs transition-colors cursor-pointer shadow-xs">
                                Invite more residents
                            </button>
                        </div>
                    </div>

                </div>
            </main>
        </div>
    )
}